pub fn greeting(name: &str) -> String {
    let first = name.chars().next().unwrap();
    let first_upper = first.to_uppercase().to_string();
    format!("Hello, {first_upper}{}!", &name[first.len_utf8()..])
}

#[cfg(test)]
mod tests {
    use super::greeting;

    #[test]
    fn greets_world() {
        assert_eq!(greeting("world"), "Hello, World!");
    }
}
